from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(19,'probabilites','Hasard et probabilités','4 · Données, hasard et programmation',
'Expérience · Issue · Évènement · Équiprobabilité · Fréquence',
['Décrire une expérience aléatoire et ses issues.','Attribuer une probabilité dans des cas équiprobables.','Comparer probabilité et fréquence observée.'],['Fractions et fréquences.'],[
page(1,'Décrire ce qui peut arriver',
bloc('definition',r'Une expérience aléatoire est une expérience dont on ne connaît pas à l’avance le résultat. Une issue est un résultat possible. Un évènement réunit une ou plusieurs issues. Pour un dé, « obtenir un nombre pair » réunit 2, 4 et 6.'),
r'@FIG:cours-probabilites@',
bloc('propriete',r'Une probabilité est comprise entre 0 et 1. Un évènement impossible a une probabilité 0 ; un évènement certain une probabilité 1. Une chance sur quatre correspond à $1/4=0{,}25=25\,\%$.'),
bloc('attention',r'Une probabilité très faible n’est pas zéro. Un résultat très probable n’est pas certain. Le hasard ne permet pas de prédire chaque résultat individuel.')),
page(2,'Compter et expérimenter',
bloc('definition',r'On parle d’équiprobabilité lorsque toutes les issues retenues ont la même probabilité. Pour un dé équilibré, les six faces sont équiprobables.'),
bloc('propriete',r'En cas d’équiprobabilité, la probabilité d’un évènement est le nombre d’issues favorables divisé par le nombre total d’issues. Pour un dé équilibré, obtenir plus de 4 a pour probabilité $2/6=1/3$.'),
bloc('exemple',r'Une urne contient trois boules rouges et deux bleues, indiscernables au toucher. Chaque boule a la même chance d’être tirée, mais les deux couleurs n’ont pas la même chance : $3/5$ pour rouge et $2/5$ pour bleu.'),
bloc('savoirfaire',r'Répéter la même expérience en remettant les conditions de départ, noter chaque résultat puis calculer effectifs et fréquences. Une fréquence observée n’est pas nécessairement égale à la probabilité du modèle, surtout sur peu d’essais.','Confronter au réel'))
],[
E('Les issues d’un dé',r'On lance un dé équilibré à six faces numérotées de 1 à 6. Lister les issues.',r'Les issues sont $\res{1,2,3,4,5,6}$. Une issue décrit ici le numéro de la face obtenue.','Préciser ce qu’on observe.','assert list(range(1,7))==[1,2,3,4,5,6]'),
E('Une pièce équilibrée',r'Quelle est la probabilité d’obtenir pile en lançant une pièce équilibrée ? Donner trois écritures.',r'Les deux faces sont équiprobables : $\res{1/2=0{,}5=50\,\%}$.','Identifier les issues équiprobables.','assert Rational(1,2)==Rational(".5")==Rational(50,100)'),
E('Une échelle de probabilité',r'Placer sur l’échelle de probabilité les évènements : A « obtenir 8 avec le dé précédent » ; B « obtenir un nombre inférieur à 7 avec ce dé » ; C « obtenir pile avec une pièce équilibrée » ; D « ne pas trouver la bonne combinaison au loto » ; E « obtenir dix fois de suite 1 avec le dé ».',r'8 n’est pas une issue : A est impossible, probabilité $\res0$. Toutes les faces sont inférieures à 7 : B est certain, probabilité $\res1$. C a pour probabilité $\res{1/2}$. D est très probable, très près de 1 sans être certain ; E est très peu probable, très près de 0 sans être impossible.','Comparer l’évènement à toutes les issues.','assert len([a for a in range(1,7) if a==8])==0 and len([a for a in range(1,7) if a<7])==6 and 0<Rational(1,6)**10<Rational(1,10**6)',figure='proba-3'),
E('Une face donnée',r'Quelle est la probabilité d’obtenir 5 sur un dé équilibré à six faces ?',r'Une seule issue sur six convient : $\res{1/6}$. Cela ne signifie pas qu’un 5 apparaîtra exactement une fois tous les six lancers.','Compter les issues favorables.','assert Rational(1,6)>0'),
E('Lire une chance sur quatre',r'Une chance sur quatre correspond-elle à 4 %, 25 % ou 40 % ?',r'$1/4=25/100=\res{25\,\%}$. Le nombre quatre est le total des parts équiprobables.','Convertir la fraction en pourcentage.','assert Rational(1,4)==Rational(25,100)'),
E('Un évènement à plusieurs issues',r'Pour un dé équilibré, calculer la probabilité d’obtenir un nombre pair.',r'Les issues favorables sont 2, 4 et 6 : $3/6=\res{1/2}$. Trois issues différentes peuvent réaliser le même évènement.','Lister avant de compter.','assert [a for a in range(1,7) if a%2==0]==[2,4,6]'),
E('Une urne',r'Une urne contient quatre boules rouges, trois bleues et une verte, toutes indiscernables au toucher. Donner la probabilité de tirer bleu.',r'Il y a $4+3+1=8$ boules, dont trois bleues. La probabilité vaut $\res{3/8=37{,}5\,\%}$. Les boules sont équiprobables, pas les couleurs.','Compter les objets, pas seulement les couleurs.','assert Rational(3,4+3+1)==Rational(3,8)',figure='proba-7'),
E('Une roue régulière',r'Une roue équilibrée est partagée en huit secteurs égaux, numérotés de 1 à 8. Calculer la probabilité d’un numéro supérieur à 5.',r'Les secteurs 6, 7 et 8 conviennent, sur huit secteurs équiprobables : $\res{3/8}$.','Utiliser l’égalité des secteurs.','assert len([a for a in range(1,9) if a>5])==3',figure='proba-8'),
E('Des jetons identifiés',r'On tire un jeton au hasard parmi R1, R2, R3, B1, B2 et V1, indiscernables au toucher. Calculer la probabilité d’obtenir un jeton portant le numéro 1.',r'Les jetons R1, B1 et V1 conviennent : $3/6=\res{1/2}$. Leur couleur ne change pas le nombre inscrit.','Définir précisément l’évènement.','assert len([a for a in ["R1","R2","R3","B1","B2","V1"] if a.endswith("1")])==3',figure='proba-9'),
E('Fréquence observée',r'Une pièce donne 18 piles en 40 lancers. Calculer la fréquence de pile. Cela prouve-t-il que la pièce n’est pas équilibrée ?',r'La fréquence vaut $18/40=\res{0{,}45=45\,\%}$. Cet écart à 50 % ne suffit pas à prouver un déséquilibre ; les résultats d’une série aléatoire peuvent varier.','Séparer observation et probabilité supposée.','assert Rational(18,40)==Rational(".45")'),
E('Préparer une expérience',r'Décrire une expérience pour observer la fréquence de rouge dans une urne avec deux rouges et trois bleues. Pourquoi faut-il remettre la boule ?',r'Tirer sans regarder, noter la couleur, remettre la boule puis mélanger, et recommencer. La remise maintient deux rouges sur cinq à chaque essai : la probabilité du modèle reste $\res{2/5}$. Sans remise, la composition change.','Conserver les mêmes conditions d’essai.','assert Rational(2,5)==Rational(".4")',figure='proba-11'),
E('Comparer deux jeux',r'A fait gagner sur une face marquée parmi six faces équilibrées. B fait gagner sur trois jetons parmi dix jetons équiprobables. Quel jeu offre la plus grande probabilité de gagner ?',r'A donne $1/6=5/30$ ; B donne $3/10=9/30$. La probabilité est plus grande dans le jeu $\res B$. Cela ne garantit pas le gain au prochain essai.','Comparer deux fractions.','assert Rational(3,10)>Rational(1,6)'),
E('Construire une urne',r'Une urne de douze boules doit donner une probabilité de rouge égale à $1/3$. Combien de rouges faut-il ? Les autres boules seront bleues.',r'Un tiers de douze vaut $\res4$ : il faut quatre rouges et $\res8$ bleues. Contrôle : $4/12=1/3$.','Passer de la proportion à l’effectif.','assert Rational(4,12)==Rational(1,3) and 12-4==8',figure='proba-13'),
E('Une fausse compensation',r'Une pièce équilibrée donne pile cinq fois de suite. Lina affirme que le prochain lancer doit donner face pour compenser. Peut-elle le garantir ?',r'Non. Si les conditions restent celles d’une pièce équilibrée à chaque lancer, pile et face ont encore chacun une probabilité $\res{1/2}$. Une série passée n’impose pas une compensation au lancer suivant.','Distinguer tendance de fréquence et résultat imposé.','assert Rational(1,2)==Rational(50,100)'),
E('Deux relevés différents',r'On observe 6 succès sur 10 essais puis 46 succès sur 100 essais dans une expérience dont le modèle donne $1/2$. Comparer les fréquences et leurs écarts à $1/2$. Peut-on exiger que chaque série plus longue soit plus proche ?',r'Les fréquences sont 0,6 et 0,46 ; leurs écarts à 0,5 valent $\res{0{,}10}$ et $\res{0{,}04}$. La seconde est ici plus proche, mais chaque série plus longue n’est pas obligée de l’être : les fluctuations restent possibles.','Calculer les écarts sans transformer une tendance en garantie.','assert Abs(Rational(6,10)-Rational(1,2))==Rational(".1") and Abs(Rational(46,100)-Rational(1,2))==Rational(".04")')
],reperes=['Expérience, issue et évènement','Échelle de probabilité et écritures','Calcul en équiprobabilité','Répétitions, effectifs et fréquences'],deco='probabilites')

chapitre(20,'programmation','Penser et programmer par blocs','4 · Données, hasard et programmation',
'Entrées · Sorties · Expressions · Séquences · Répétitions simples',
['Lire et modifier un programme simple.','Représenter une formule par des blocs.','Comprendre une répétition inconditionnelle.'],['Formules et angles des polygones rencontrés.'],[
page(1,'Lire une séquence et une formule',
bloc('definition',r'Un programme est une suite d’instructions exécutées dans un ordre précis. Une entrée est une donnée fournie au programme ; une sortie est une information produite. En Cinquième, une donnée saisie est lue et utilisée sans étudier les mises à jour complexes de variables.'),
r'@FIG:cours-programme@',
bloc('savoirfaire',r'Pour une entrée 4, le calcul $3\times\text{réponse}+2$ donne 14. Les blocs imbriqués décrivent les parenthèses : multiplier après addition n’est pas la même chose qu’additionner après multiplication.','Prévoir avant d’exécuter'),
bloc('attention',r'Le texte \texttt{réponse} représente ici la donnée saisie. Une phrase affichée n’est pas une nouvelle entrée. Identifier où le programme demande, calcule et affiche.')),
page(2,'Répéter une séquence linéaire',
bloc('definition',r'Une boucle inconditionnelle répète un nombre fixé de fois la même suite d’instructions. « Répéter 4 fois : avancer de 60, tourner de $90^\circ$ » trace un carré si le stylo est baissé.'),
r'@FIG:cours-boucle@',
bloc('savoirfaire',r'L’angle du bloc « tourner » est le changement de direction du déplacement. Pour un triangle équilatéral, tourner de $120^\circ$ à chaque sommet, et non de son angle intérieur de $60^\circ$.','Distinguer angle intérieur et rotation'),
bloc('attention',r'Vérifier le point de départ, la direction initiale, le stylo et le nombre de répétitions. Une boucle de quatre pas ne trace pas forcément un carré : les longueurs et les angles doivent aussi convenir.'))
],[
E('Entrée et sortie',r'Le programme demande un nombre puis dit « réponse + 5 ». Identifier l’entrée et la sortie pour une saisie de 7.',r'L’entrée est $\res7$. La sortie calculée est $7+5=\res{12}$. Le programme ne dit pas le texte « réponse + 5 » : il évalue l’expression du bloc.','Distinguer donnée saisie et résultat.','assert 7+5==12',figure='prog-1'),
E('Prévoir une formule',r'Prévoir la sortie du programme pour une entrée de 4.',r'Le bloc calcule $3\times4+2=\res{14}$. Le produit se fait avant l’addition.','Lire les blocs imbriqués.','assert 3*4+2==14',figure='prog-2'),
E('Des parenthèses',r'Le programme calcule $3(\text{réponse}+2)$. Quelle sortie donne l’entrée 4 ?',r'On calcule d’abord $4+2=6$, puis $3\times6=\res{18}$.','Respecter l’emboîtement.','assert 3*(4+2)==18',figure='prog-3'),
E('Une aire',r'Le programme calcule le carré de la réponse. Quelle sortie donne une entrée de 5, interprétée en cm ?',r'$5\times5=\res{25}$. Si la réponse est un côté en cm, la sortie représente une aire de $\res{25\ \mathrm{cm}^2}$.','Interpréter la formule.','assert 5**2==25',figure='prog-4'),
E('Deux déplacements',r'Le lutin, dirigé vers la droite, avance de 30 puis de 50 pas, sans tourner. Quelle distance parcourt-il ?',r'Il parcourt $30+50=\res{80}$ pas vers la droite. Les deux instructions sont exécutées successivement.','Lire une séquence dans l’ordre.','assert 30+50==80',figure='prog-5'),
E('Modifier un paramètre',r'Le programme affiche $2\times\text{réponse}+4$. Modifier un seul nombre pour qu’il affiche le triple de la réponse plus 4. Tester avec 6.',r'Remplacer 2 par 3. La nouvelle sortie pour 6 vaut $3\times6+4=\res{22}$. L’addition de 4 reste après le produit.','Modifier le coefficient utile.','assert 3*6+4==22',figure='prog-6'),
E('Tracer un carré',r'Identifier la figure tracée par « répéter 4 fois : avancer de 50 ; tourner à gauche de $90^\circ$ ». Donner son périmètre en pas.',r'Les quatre côtés sont égaux et les quatre angles sont droits : un $\res{carré}$. Le périmètre vaut $4\times50=\res{200}$ pas. Le lutin revient au départ et retrouve sa direction.','Relier répétitions et côtés.','assert 4*50==200 and 4*90==360',figure='prog-7'),
E('Un rectangle en boucle',r'Le programme répète deux fois : avancer de 80, tourner de 90 degrés, avancer de 40, tourner de 90 degrés. Identifier la figure et son périmètre.',r'Il trace un $\res{rectangle}$ de côtés 80 et 40 pas. Le périmètre vaut $2(80+40)=\res{240}$ pas. Chaque tour de boucle trace deux côtés.','Compter les instructions à l’intérieur de la boucle.','assert 2*(80+40)==240 and 2*(90+90)==360',figure='prog-8'),
E('Un triangle équilatéral',r'Le programme répète trois fois : avancer de 60, tourner de $120^\circ$. Expliquer pourquoi la figure est un triangle équilatéral.',r'Il trace trois segments égaux. Les changements de direction de $120^\circ$ donnent des angles intérieurs de $180-120=60^\circ$. La figure se ferme : c’est un $\res{triangle\ équilatéral}$.','Distinguer le virage de l’angle intérieur.','assert 3*120==360 and 180-120==60',figure='prog-9'),
E('L’ordre des blocs',r'Comparer les trajets « avancer de 40, tourner à gauche de 90 degrés » et « tourner à gauche de 90 degrés, avancer de 40 », avec une direction initiale vers la droite.',r'Le premier finit 40 pas à droite du départ ; le second 40 pas au-dessus. Les orientations finales sont identiques, mais les positions diffèrent. L’ordre des instructions a donc une conséquence.','Suivre position et direction séparément.','assert (40,0)!=(0,40)',figure='prog-10'),
E('Un pentagone régulier',r'Un script répète cinq fois : avancer de 40, tourner de $72^\circ$. Expliquer la fermeture et calculer le périmètre.',r'Les cinq changements de direction totalisent $5\times72=360^\circ$. Les cinq côtés égaux forment ici un pentagone régulier fermé ; son périmètre vaut $\res{200}$ pas.','Relier un tour complet aux virages.','assert 5*72==360 and 5*40==200',figure='prog-11'),
E('Une ligne brisée',r'Le script répète trois fois : avancer de 30, tourner à gauche de 90 degrés, avancer de 20, tourner à droite de 90 degrés. Décrire le déplacement final.',r'Chaque répétition ajoute 30 pas vers la droite et 20 vers le haut, puis rétablit la direction de départ. Après trois fois : $\res{90}$ pas à droite et $\res{60}$ vers le haut. Le dessin est un escalier.','Décrire un motif puis le répéter.','assert 3*30==90 and 3*20==60',figure='prog-12'),
E('Réparer un carré incomplet',r'Un script répète trois fois « avancer de 50, tourner de 90 degrés » pour dessiner un carré. Expliquer le défaut et le corriger.',r'Il manque le quatrième côté. Remplacer trois répétitions par $\res4$. Le quatrième déplacement ferme la figure ; le dernier virage rétablit l’orientation initiale.','Compter les côtés réellement tracés.','assert 3*90==270 and 4*90==360',figure='prog-13'),
E('Une formule de volume',r'Un script demande le côté d’un cube et affiche réponse × réponse × réponse. Prévoir les sorties pour 2 et 3, puis préciser les unités si le côté est en cm.',r'Les sorties sont $2^3=\res8$ et $3^3=\res{27}$. Elles représentent des volumes en $\res{cm^3}$. Une seule donnée saisie est lue trois fois dans le calcul.','Reconnaître un produit répété.','assert 2**3==8 and 3**3==27',figure='prog-14'),
E('Concevoir puis contrôler',r'Écrire un programme demandant une longueur en cm et affichant le périmètre d’un carré de ce côté. Tester pour 2,5 et 0. Préciser ce que représente le test 0.',r'Demander le côté puis dire $4\times\text{réponse}$. Pour 2,5, la sortie est $\res{10\ \mathrm{cm}}$ ; pour 0, elle est 0. Ce test contrôle la formule à la frontière, mais un côté nul ne donne pas un carré non aplati.','Séparer le calcul et le sens géométrique.','assert 4*Rational("2.5")==10 and 4*0==0',figure='prog-15')
],reperes=['Instructions, entrées et sorties','Expressions informatiques et prévision','Analyse et modification de paramètres','Boucle inconditionnelle simple'],deco='algorithmique')
